import 'package:flutter/foundation.dart'; import '../models/pickup.dart'; import '../repositories/pickup_repository.dart'; class PickupProvider extends ChangeNotifier { PickupProvider(this.repository); final PickupRepository repository; List<Pickup> pickups=[]; bool loading=false; Future<void> load() async { loading=true;notifyListeners(); try{pickups=await repository.list();}finally{loading=false;notifyListeners();} } }
